    # Edge markers are paired same-color blocks on perpendicular boundaries.
    # A horizontal edge block seeds a vertical beam; a vertical edge block seeds a horizontal beam.
    # Find colored boundary block on top/bottom, and its run length.
    boundaries = []
    for r in (0, h-1):
        for c in range(w):
            v = grid[r][c]
            if v != bg:
                e=c
                while e+1<w and grid[r][e+1]==v: e+=1
                boundaries.append(('h',r,c,e,v))
                break
    for c in (0,w-1):
        for r in range(h):
            v=grid[r][c]
            if v != bg:
                e=r
                while e+1<h and grid[e+1][c]==v: e+=1
                boundaries.append(('v',c,r,e,v))
                break
    # Demonstrated pattern: boundary block is preserved; matching marker pixels build rectangular bars.
    # Locate isolated non-background objects, then extend their color back toward the opposing boundary.
    for typ, fixed, start, end, color in boundaries:
        if typ == 'h':
            # horizontal edge block indicates vertical projection of markers of another color
            marker_colors=[v for v in vals if v not in (bg,color)]
            if not marker_colors: continue
            mc=marker_colors[0]
            for r in range(1,h-1):
                for c in range(w):
                    if grid[r][c]==mc:
                        out[r][c]=4
                        # continue toward the nearby block column, filling the rectangle
                        if fixed==0:
                            for rr in range(1,r):
