                        else:
                            for rr in range(r+1,h-1):
                                if grid[rr][c]==bg: out[rr][c]=mc
        else:
            # edge-column pair projects the marker color horizontally from marker to edge
            marker_colors=[v for v in vals if v not in (bg,color)]
            if not marker_colors: continue
            mc=marker_colors[0]
            for r in range(h):
                for c in range(1,w-1):
                    if grid[r][c]==mc:
                        out[r][c]=4
                        if fixed==w-1:
                            for x in range(c+1,w-1):
                                if grid[r][x]==bg: out[r][x]=mc
                        else:
                            for x in range(1,c):
                                if grid[r][x]==bg: out[r][x]=mc
    # The adjacent edge object (the other color pair) defines filled rectangular region by alignment.
