 "content": "def transform(grid):
    h,w=len(grid),len(grid[0])
    from collections import Counter
    cnt=Counter(v for row in grid for v in row)
    bg=cnt.most_common(1)[0][0]
    out=[row[:] for row in grid]
    # Boundary rails of color A meet interior marker chain of color B.
    # Convert each marker into 4 and extend its color in a straight line toward the nearest rail.
    rails=[]
    for r in range(h):
        for c in range(w):
            v=grid[r][c]
            if v!=bg and (r in (0,h-1) or c in (0,w-1)):
                rails.append(v)
    railset=set(rails)
    candidates=[v for v in cnt if v!=bg and v not in railset]
    if not candidates:return out
    m=candidates[0]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==m:
                out[r][c]=4
                # extend horizontally toward the nearest marker/edge rail
                left,right=c, c
                while left>0 and grid[r][left-1]==bg:left-=1
                while right<w-1 and grid[r][right+1]==bg:right+=1
                # choose ray toward closest boundary rail
                if c < w//2:
                    for x in range(c+1,right+1):
                        if grid[r][x]==bg:out[r][x]=m
                else:
                    for x in range(left,c):
                        if grid[r][x]==bg:out[r][x]=m
    return out
